param(
    [string]$ProjectRoot = "",
    [switch]$SkipInitialBuild,
    [switch]$SkipFinalBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

try {
    [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
    $OutputEncoding = New-Object System.Text.UTF8Encoding($false)
} catch {}

$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$Marker = "ORCALY_OWNER_FINANCE_V1"

if ([string]::IsNullOrWhiteSpace($ProjectRoot)) {
    $ProjectRoot = (Get-Location).Path
} else {
    $ProjectRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path
}

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot (".orcaly-backups\owner-finance-" + $Timestamp)
$ChangedFiles = New-Object System.Collections.Generic.List[string]
$BackupMap = @{}

function Step([string]$Text) {
    Write-Host ""
    Write-Host ("==> " + $Text) -ForegroundColor Cyan
}

function Ok([string]$Text) {
    Write-Host ("[OK] " + $Text) -ForegroundColor Green
}

function Warn([string]$Text) {
    Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow
}

function Sha([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return "" }
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant()
}

function Backup([string]$Relative) {
    $source = Join-Path $ProjectRoot ($Relative -replace "/", "\")
    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { return }
    if ($BackupMap.ContainsKey($Relative)) { return }

    $dest = Join-Path $BackupRoot ($Relative -replace "/", "\")
    [IO.Directory]::CreateDirectory((Split-Path -Parent $dest)) | Out-Null
    Copy-Item -LiteralPath $source -Destination $dest -Force
    $BackupMap[$Relative] = $dest
}

function Rollback {
    foreach ($relative in @($ChangedFiles)) {
        $target = Join-Path $ProjectRoot ($relative -replace "/", "\")

        if ($BackupMap.ContainsKey($relative)) {
            Copy-Item -LiteralPath $BackupMap[$relative] -Destination $target -Force
            Warn ("Restaurado: " + $relative)
        } elseif (Test-Path -LiteralPath $target -PathType Leaf) {
            Remove-Item -LiteralPath $target -Force
            Warn ("Removido arquivo criado: " + $relative)
        }
    }
}

try {
    Write-Host ""
    Write-Host "ORÇALY - FINANCEIRO DO OWNER V1" -ForegroundColor Cyan
    Write-Host "Receita, taxas, marketplace, comissões, bruto e líquido." -ForegroundColor DarkCyan

    if (-not (Test-Path -LiteralPath (Join-Path $ProjectRoot "package.json"))) {
        throw "Execute na raiz do projeto Orçaly."
    }

    Set-Location $ProjectRoot
    [IO.Directory]::CreateDirectory($BackupRoot) | Out-Null

    $json = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String("")
    )
    $decoded = ConvertFrom-Json -InputObject $json
    $Specs = New-Object System.Collections.Generic.List[object]

    foreach ($item in $decoded) {
        $Specs.Add($item)
    }

    Step "Auditando o backoffice já aplicado"

    $ownerFile = Join-Path $ProjectRoot "components\admin\OwnerBackofficeClient.tsx"
    if (-not (Test-Path -LiteralPath $ownerFile)) {
        throw "OwnerBackofficeClient não encontrado. Aplique primeiro o backoffice V4."
    }

    $ownerText = [IO.File]::ReadAllText($ownerFile)
    if (-not $ownerText.Contains("ORCALY_OWNER_BACKOFFICE_V2")) {
        throw "O backoffice V2 não foi identificado no projeto local."
    }

    foreach ($spec in $Specs) {
        $relative = [string]$spec.path
        $full = Join-Path $ProjectRoot ($relative -replace "/", "\")
        $current = Sha $full
        $desired = [string]$spec.desired_sha256

        if ($current -eq $desired) {
            Ok ($relative + " já está atualizado.")
            continue
        }

        if ([bool]$spec.new_file) {
            if (Test-Path -LiteralPath $full -PathType Leaf) {
                throw "$relative já existe com conteúdo diferente. O patch não vai sobrescrever."
            }
            Ok ($relative + " será criado.")
        } else {
            if ($current -ne [string]$spec.expected_sha256) {
                throw "$relative mudou desde a V4. O patch não vai sobrescrever uma alteração local não auditada."
            }
            Ok ($relative + " corresponde exatamente ao backoffice V4 auditado.")
        }
    }

    if (-not $SkipInitialBuild) {
        Step "Build inicial"
        & npm.cmd run build
        if ($LASTEXITCODE -ne 0) {
            throw "O projeto já falha no build antes do financeiro. Nada foi alterado."
        }
        Ok "Build inicial passou."
    }

    Step "Aplicando financeiro do owner"

    foreach ($spec in $Specs) {
        $relative = [string]$spec.path
        $full = Join-Path $ProjectRoot ($relative -replace "/", "\")
        $desired = [string]$spec.desired_sha256

        if ((Sha $full) -eq $desired) {
            continue
        }

        if (Test-Path -LiteralPath $full -PathType Leaf) {
            Backup $relative
        }

        [IO.Directory]::CreateDirectory((Split-Path -Parent $full)) | Out-Null
        $bytes = [Convert]::FromBase64String([string]$spec.content_b64)
        $content = [Text.Encoding]::UTF8.GetString($bytes)
        [IO.File]::WriteAllText($full, $content, $Utf8NoBom)
        $ChangedFiles.Add($relative)
        Ok ("Aplicado: " + $relative)
    }

    Step "Validação estrutural"

    $financeRoute = Join-Path $ProjectRoot "app\api\admin\finance\route.ts"
    $financeClient = Join-Path $ProjectRoot "components\admin\OwnerFinanceClient.tsx"
    $financePage = Join-Path $ProjectRoot "app\admin\financeiro\page.tsx"

    foreach ($path in @($financeRoute, $financeClient, $financePage)) {
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            throw "Arquivo esperado não foi criado: $path"
        }

        if (-not ([IO.File]::ReadAllText($path)).Contains($Marker)) {
            throw "Marcador financeiro ausente em: $path"
        }
    }

    $ownerAfter = [IO.File]::ReadAllText($ownerFile)
    if (-not $ownerAfter.Contains('href="/admin/financeiro"')) {
        throw "O link Financeiro não entrou no painel owner."
    }

    & git --no-pager diff --check -- `
        "components/admin/OwnerBackofficeClient.tsx" `
        "app/api/admin/finance/route.ts" `
        "components/admin/OwnerFinanceClient.tsx" `
        "app/admin/financeiro/page.tsx"

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problema no patch financeiro."
    }

    Ok "Estrutura do financeiro validada."

    Step "Lint apenas dos novos arquivos financeiros"
    & npx.cmd eslint `
        "app/api/admin/finance/route.ts" `
        "components/admin/OwnerFinanceClient.tsx" `
        "app/admin/financeiro/page.tsx"

    if ($LASTEXITCODE -ne 0) {
        Warn "O lint dos novos arquivos encontrou avisos/erros. O build final decidirá se há regressão de compilação."
    } else {
        Ok "Lint dos novos arquivos passou."
    }

    if (-not $SkipFinalBuild) {
        Step "Build final"
        & npm.cmd run build
        if ($LASTEXITCODE -ne 0) {
            throw "O build final falhou após adicionar o financeiro."
        }
        Ok "Build final passou."
    }

    Step "Resumo"
    Write-Host ""
    Write-Host "Financeiro owner aplicado." -ForegroundColor Green
    Write-Host "Rota: /admin/financeiro"
    Write-Host "API: /api/admin/finance"
    Write-Host "Período: seletor mensal"
    Write-Host ""
    Write-Host "Inclui:"
    Write-Host " - Receita de assinaturas"
    Write-Host " - Taxa real do Mercado Pago quando conciliável"
    Write-Host " - GMV do marketplace separado da receita do Orçaly"
    Write-Host " - Taxa do Orçaly no marketplace"
    Write-Host " - Taxa MP do fluxo marketplace"
    Write-Host " - Líquido dos lojistas"
    Write-Host " - Comissões geradas"
    Write-Host " - Comissões efetivamente pagas"
    Write-Host " - Receita bruta, saídas e líquido de caixa"
    Write-Host " - Comparação com mês anterior"
    Write-Host " - Movimento diário e tabelas de conciliação"
    Write-Host ""
    Write-Host "Nenhuma migration, commit, push ou deploy foi executado." -ForegroundColor Cyan
    Write-Host ("Backup: " + $BackupRoot)
}
catch {
    Write-Host ""
    Write-Host ("[ERRO] " + $_.Exception.Message) -ForegroundColor Red

    if ($ChangedFiles.Count -gt 0) {
        Warn "Executando rollback do patch financeiro."
        Rollback
    }

    Write-Host ("Diagnóstico/backup: " + $BackupRoot) -ForegroundColor Yellow
    exit 1
}
